  if (!Array.isArray(arr1) || arr1.length < 1 || arr1.length > 100000) return 'arr1 needs 1 to 10^5 values.';
  if (!Array.isArray(arr2) || arr2.length < 1 || arr2.length > 100000) return 'arr2 needs 1 to 10^5 values.';
  const bad = (v) => !Number.isInteger(v) || v < 0 || v > 1000000000;
  if (arr1.some(bad)) return 'Each arr1 value is an integer from 0 to 10^9.';
  if (arr2.some(bad)) return 'Each arr2 value is an integer from 0 to 10^9.';
  return null;
}

